import heapq

def bellman_ford(edges, num_nodes, source):
    distances = {node: float('inf') for node in range(num_nodes)}
    distances[source] = 0
    predecessors = {node: None for node in range(num_nodes)}

    # Relax edges repeatedly
    for _ in range(num_nodes - 1):
        for u, v, weight in edges:
            if distances[u] != float('inf') and distances[u] + weight < distances[v]:
                distances[v] = distances[u] + weight
                predecessors[v] = u

    # Check for negative cycles
    for u, v, weight in edges:
        if distances[u] != float('inf') and distances[u] + weight < distances[v]:
            raise ValueError("Graph contains a negative cycle")

    return distances, predecessors

def dijkstra(edges, num_nodes, source, target):
    # Convert edge list to an adjacency list for Dijkstra
    adj = {i: [] for i in range(num_nodes)}
    for u, v, weight in edges:
        adj[u].append((v, weight))

    distances = {node: float('inf') for node in range(num_nodes)}
    distances[source] = 0
    predecessors = {node: None for node in range(num_nodes)}
    priority_queue = [(0, source)]  # (distance, node)

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we have found a shorter path, skip
        if current_distance > distances[current_node]:
            continue

        if current_node == target:
            break

        for neighbor, weight in adj[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                predecessors[neighbor] = current_node
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances, predecessors

def get_path(predecessors, target):
    path = []
    current = target
    while current is not None:
        path.append(current)
        current = predecessors[current]
    return path[::-1]

# Given graph edges
raw_edges = [
    (0, 1, 3),
    (0, 2, 5),
    (0, 3, 8),
    (0, 4, 9),
    (0, 5, 10),
    (1, 6, 1),
    (2, 1, -3),
    (2, 6, 8),
    (3, 6, 8),
    (4, 6, 8),
    (5, 6, 8),
]
source = 0
target = 6

# Determine the number of nodes
num_nodes = max(max(u, v) for u, v, _ in raw_edges) + 1

# Check for negative weights
has_negative_weights = any(weight < 0 for _, _, weight in raw_edges)

if has_negative_weights:
    print("Graph contains negative weights. Using Bellman-Ford algorithm.")
    final_distances, final_predecessors = bellman_ford(raw_edges, num_nodes, source)
else:
    print("Graph contains no negative weights. Using Dijkstra's algorithm.")
    final_distances, final_predecessors = dijkstra(raw_edges, num_nodes, source, target)

# Print the results
if final_distances[target] == float('inf'):
    print(f"No path found from {source} to {target}")
else:
    shortest_distance = final_distances[target]
    shortest_path = get_path(final_predecessors, target)

    print(f"Shortest distance from {source} to {target}: {shortest_distance}")
    print(f"Shortest path: {' -> '.join(map(str, shortest_path))}")

